vector<int> sortArrayByParity(vector<int>& nums) {
    vector<int> evens, odds;
    for (int n : nums) {
        if (n % 2 == 0) evens.push_back(n); else odds.push_back(n);
    }
    evens.insert(evens.end(), odds.begin(), odds.end());
    return evens;
}

