    vector<int> nums1 = {3, 1, 2, 4};
    for (int x : sortArrayByParity(nums1)) cout << x << " ";
    cout << endl;
    vector<int> nums2 = {0};
    for (int x : sortArrayByParity(nums2)) cout << x << " ";
    cout << endl;
    return 0;
}

