def sort_array_by_parity(nums):
    arr = nums[:]
    left, right = 0, len(arr) - 1

    while left < right:
        if arr[left] % 2 == 0:
            left += 1
        elif arr[right] % 2 == 1:
            right -= 1
        else:
            arr[left], arr[right] = arr[right], arr[left]
            left += 1
            right -= 1

    return arr


