#include <bits/stdc++.h>
using namespace std;

vector<int> sortArrayByParity(vector<int>& nums) {
    vector<int> arr = nums;
    int left = 0, right = arr.size() - 1;

    while (left < right) {
        if (arr[left] % 2 == 0) {
            left++;
        } else if (arr[right] % 2 == 1) {
            right--;
        } else {
            swap(arr[left], arr[right]);
            left++;
            right--;
        }
    }
    return arr;
}

int main() {
    vector<int> nums1 = {3, 1, 2, 4};
    for (int x : sortArrayByParity(nums1)) cout << x << " ";
    cout << endl;
    vector<int> nums2 = {0};
    for (int x : sortArrayByParity(nums2)) cout << x << " ";
    cout << endl;
    return 0;
